-- RA-BIO-INC-01 (inclusion): 病患年齡須滿十八歲。
c_ra_bio_inc_01 AS (
  SELECT b.pid, b.index_date, (((year(b.index_date) - year(b.birth_date) - CASE WHEN strftime(b.index_date, '%m-%d') < strftime(b.birth_date, '%m-%d') THEN 1 ELSE 0 END) >= 18)) AS v,
         concat_ws(';', NULL) AS ev
  FROM base b
  ),
a_ra_bio_inc_02_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d <= (b.index_date + -180)
  GROUP BY b.pid, b.index_date),
a_ra_bio_inc_02_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ra_bio_inc_02_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_RHEUMATOID_ARTHRITIS' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d <= (b.index_date + -180)
  GROUP BY b.pid, b.index_date),
-- RA-BIO-INC-02 (inclusion): 經診斷為類風濕關節炎且病程達六個月以上。
c_ra_bio_inc_02 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_ra_bio_inc_02_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ra_bio_inc_02_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ra_bio_inc_02_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_ra_bio_inc_02_1.ev, a_ra_bio_inc_02_1_off.ev, a_ra_bio_inc_02_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_inc_02_1 ON a_ra_bio_inc_02_1.pid = b.pid AND a_ra_bio_inc_02_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_02_1_nd ON a_ra_bio_inc_02_1_nd.pid = b.pid AND a_ra_bio_inc_02_1_nd.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_02_1_off ON a_ra_bio_inc_02_1_off.pid = b.pid AND a_ra_bio_inc_02_1_off.index_date = b.index_date),
a_ra_bio_inc_03_1_p AS (
  SELECT b.pid, b.index_date, m.mid, greatest(coalesce(m.start, m.authored), (b.index_date + -730)) AS s,
         least(coalesce(m."end", m.start, m.authored), b.index_date) AS e
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_METHOTREXATE' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_METHOTREXATE' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND coalesce(m.start, m.authored) IS NOT NULL
    AND greatest(coalesce(m.start, m.authored), (b.index_date + -730)) <= least(coalesce(m."end", m.start, m.authored), b.index_date)),
a_ra_bio_inc_03_1_g AS (
  SELECT *, CASE WHEN s <= max(e) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) + 31 THEN 0 ELSE 1 END AS new_island
  FROM a_ra_bio_inc_03_1_p),
a_ra_bio_inc_03_1_i AS (
  SELECT *, sum(new_island) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS UNBOUNDED PRECEDING) AS island FROM a_ra_bio_inc_03_1_g),
a_ra_bio_inc_03_1 AS (
  SELECT pid, index_date, max(len) AS days, string_agg(ev, ';' ORDER BY ev) AS ev FROM (
    SELECT pid, index_date, island, (max(e) - min(s)) + 1 AS len,
           string_agg(mid, ';' ORDER BY s, mid) AS ev FROM a_ra_bio_inc_03_1_i GROUP BY pid, index_date, island)
  GROUP BY pid, index_date),
a_ra_bio_inc_03_1_o AS (
  SELECT b.pid, b.index_date, count(*) AS n, string_agg(m.mid, ';' ORDER BY m.mid) AS ev
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_METHOTREXATE' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_METHOTREXATE' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND (coalesce(m.start, m.authored) IS NULL
         OR (m."end" IS NULL AND coalesce(m.start, m.authored) <= b.index_date))
  GROUP BY b.pid, b.index_date),
-- RA-BIO-INC-03 (inclusion): 曾使用 methotrexate 治療至少六個月（連續使用，中斷不超過三十日）而療效不彰。
c_ra_bio_inc_03 AS (
  SELECT b.pid, b.index_date, (CASE WHEN coalesce(a_ra_bio_inc_03_1.days, 0) >= 180 THEN TRUE WHEN coalesce(a_ra_bio_inc_03_1_o.n, 0) > 0 THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', (CASE WHEN coalesce(a_ra_bio_inc_03_1.days, 0) >= 180 THEN a_ra_bio_inc_03_1.ev WHEN coalesce(a_ra_bio_inc_03_1_o.n, 0) > 0 THEN 'order_dates_missing;' || a_ra_bio_inc_03_1_o.ev ELSE a_ra_bio_inc_03_1.ev END)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_inc_03_1 ON a_ra_bio_inc_03_1.pid = b.pid AND a_ra_bio_inc_03_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_03_1_o ON a_ra_bio_inc_03_1_o.pid = b.pid AND a_ra_bio_inc_03_1_o.index_date = b.index_date),
a_ra_bio_inc_04_1_p AS (
  SELECT b.pid, b.index_date, m.mid, greatest(coalesce(m.start, m.authored), (b.index_date + -730)) AS s,
         least(coalesce(m."end", m.start, m.authored), b.index_date) AS e
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_CONVENTIONAL_SYNTHETIC_DMARD_OTHER_THAN_METHOTREXATE' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_CONVENTIONAL_SYNTHETIC_DMARD_OTHER_THAN_METHOTREXATE' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND coalesce(m.start, m.authored) IS NOT NULL
    AND greatest(coalesce(m.start, m.authored), (b.index_date + -730)) <= least(coalesce(m."end", m.start, m.authored), b.index_date)),
a_ra_bio_inc_04_1_g AS (
  SELECT *, CASE WHEN s <= max(e) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) + 31 THEN 0 ELSE 1 END AS new_island
  FROM a_ra_bio_inc_04_1_p),
a_ra_bio_inc_04_1_i AS (
  SELECT *, sum(new_island) OVER (PARTITION BY pid, index_date ORDER BY s, e, mid ROWS UNBOUNDED PRECEDING) AS island FROM a_ra_bio_inc_04_1_g),
a_ra_bio_inc_04_1 AS (
  SELECT pid, index_date, max(len) AS days, string_agg(ev, ';' ORDER BY ev) AS ev FROM (
    SELECT pid, index_date, island, (max(e) - min(s)) + 1 AS len,
           string_agg(mid, ';' ORDER BY s, mid) AS ev FROM a_ra_bio_inc_04_1_i GROUP BY pid, index_date, island)
  GROUP BY pid, index_date),
a_ra_bio_inc_04_1_o AS (
  SELECT b.pid, b.index_date, count(*) AS n, string_agg(m.mid, ';' ORDER BY m.mid) AS ev
  FROM base b JOIN medication m ON m.pid = b.pid
  WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_CONVENTIONAL_SYNTHETIC_DMARD_OTHER_THAN_METHOTREXATE' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = m.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_CONVENTIONAL_SYNTHETIC_DMARD_OTHER_THAN_METHOTREXATE' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = m.nhi_code))
    AND (coalesce(m.start, m.authored) IS NULL
         OR (m."end" IS NULL AND coalesce(m.start, m.authored) <= b.index_date))
  GROUP BY b.pid, b.index_date),
-- RA-BIO-INC-04 (inclusion): 曾使用 methotrexate 以外之另一種傳統型疾病修飾抗風濕藥物至少六個月（中斷不超過三十日）而療效不彰。
c_ra_bio_inc_04 AS (
  SELECT b.pid, b.index_date, (CASE WHEN coalesce(a_ra_bio_inc_04_1.days, 0) >= 180 THEN TRUE WHEN coalesce(a_ra_bio_inc_04_1_o.n, 0) > 0 THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', (CASE WHEN coalesce(a_ra_bio_inc_04_1.days, 0) >= 180 THEN a_ra_bio_inc_04_1.ev WHEN coalesce(a_ra_bio_inc_04_1_o.n, 0) > 0 THEN 'order_dates_missing;' || a_ra_bio_inc_04_1_o.ev ELSE a_ra_bio_inc_04_1.ev END)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_inc_04_1 ON a_ra_bio_inc_04_1.pid = b.pid AND a_ra_bio_inc_04_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_04_1_o ON a_ra_bio_inc_04_1_o.pid = b.pid AND a_ra_bio_inc_04_1_o.index_date = b.index_date),
a_ra_bio_inc_05_1_tjc28 AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END)) AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) >= 0.0 AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) <= 28.0 THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'TJC28') WHERE rn = 1),
a_ra_bio_inc_05_1_sjc28 AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END)) AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) >= 0.0 AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) <= 28.0 THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
    JOIN a_ra_bio_inc_05_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 0
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'SJC28') WHERE rn = 1),
a_ra_bio_inc_05_1_ptga AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', 'mm') THEN o.value_num ELSE NULL END)) THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', 'mm') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
    JOIN a_ra_bio_inc_05_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 0
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'PTGA') WHERE rn = 1),
a_ra_bio_inc_05_1_esr AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END) >= 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
    JOIN a_ra_bio_inc_05_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 7
    WHERE o.system = 'http://loinc.org' AND o.code = '4537-7') WHERE rn = 1),
a_ra_bio_inc_05_1_crp AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END) >= 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -90) AND b.index_date
    JOIN a_ra_bio_inc_05_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 7
    WHERE o.system = 'http://loinc.org' AND o.code = '1988-5') WHERE rn = 1),
a_ra_bio_inc_05_1_v AS (
  SELECT b.pid, b.index_date, (CASE WHEN tjc28.conv IS NULL OR sjc28.conv IS NULL OR ptga.conv IS NULL THEN NULL WHEN esr.oid IS NOT NULL THEN (CASE WHEN esr.conv > 0 THEN 0.56 * sqrt(tjc28.conv) + 0.28 * sqrt(sjc28.conv) + 0.014 * ptga.conv + 0.7 * ln(esr.conv) ELSE NULL END) WHEN crp.conv IS NOT NULL THEN 0.56 * sqrt(tjc28.conv) + 0.28 * sqrt(sjc28.conv) + 0.014 * ptga.conv + 0.36 * ln(crp.conv + 1) + 0.96 ELSE NULL END) AS val, concat_ws(';', tjc28.oid || '|' || strftime(tjc28.effective, '%Y-%m-%d'), sjc28.oid || '|' || strftime(sjc28.effective, '%Y-%m-%d'), ptga.oid || '|' || strftime(ptga.effective, '%Y-%m-%d'), esr.oid || '|' || strftime(esr.effective, '%Y-%m-%d'), crp.oid || '|' || strftime(crp.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN tjc28.oid IS NULL OR tjc28.value_num IS NULL THEN 'derived_missing_input:tjc28' WHEN tjc28.conv IS NULL THEN 'derived_unit:tjc28' WHEN sjc28.oid IS NULL OR sjc28.value_num IS NULL THEN 'derived_missing_input:sjc28' WHEN sjc28.conv IS NULL THEN 'derived_unit:sjc28' WHEN ptga.oid IS NULL OR ptga.value_num IS NULL THEN 'derived_missing_input:ptga' WHEN ptga.conv IS NULL THEN 'derived_unit:ptga' WHEN esr.oid IS NOT NULL AND esr.value_num IS NULL THEN 'derived_missing_input:esr' WHEN esr.oid IS NOT NULL AND esr.conv IS NULL THEN 'derived_unit:esr' WHEN esr.oid IS NOT NULL AND esr.conv <= 0 THEN 'derived_missing_input:esr' WHEN crp.oid IS NULL OR crp.value_num IS NULL THEN 'derived_missing_input:crp' WHEN crp.conv IS NULL THEN 'derived_unit:crp' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_ra_bio_inc_05_1_tjc28 tjc28 ON tjc28.pid = b.pid AND tjc28.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_05_1_sjc28 sjc28 ON sjc28.pid = b.pid AND sjc28.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_05_1_ptga ptga ON ptga.pid = b.pid AND ptga.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_05_1_esr esr ON esr.pid = b.pid AND esr.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_05_1_crp crp ON crp.pid = b.pid AND crp.index_date = b.index_date),
a_ra_bio_inc_05_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_ra_bio_inc_05_1_v),
-- RA-BIO-INC-05 (inclusion): 申請前九十日內之疾病活動度 DAS28 大於5.1。
c_ra_bio_inc_05 AS (
  SELECT b.pid, b.index_date, (a_ra_bio_inc_05_1.val > 5.1) AS v,
         concat_ws(';', a_ra_bio_inc_05_1.ev) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_inc_05_1 ON a_ra_bio_inc_05_1.pid = b.pid AND a_ra_bio_inc_05_1.index_date = b.index_date),
a_ra_bio_inc_06_1_tjc28 AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END)) AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) >= 0.0 AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) <= 28.0 THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND (b.index_date + -90)
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'TJC28') WHERE rn = 1),
a_ra_bio_inc_06_1_sjc28 AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END)) AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) >= 0.0 AND (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) <= 28.0 THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', '1', '{#}', '{count}', '{joints}', '{score}') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND (b.index_date + -90)
    JOIN a_ra_bio_inc_06_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 0
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'SJC28') WHERE rn = 1),
a_ra_bio_inc_06_1_ptga AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', 'mm') THEN o.value_num ELSE NULL END)) THEN (CASE WHEN lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) IN ('', 'mm') THEN o.value_num ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND (b.index_date + -90)
    JOIN a_ra_bio_inc_06_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 0
    WHERE o.system = 'https://trialbox.local/fhir/CodeSystem/clinical-score' AND o.code = 'PTGA') WHERE rn = 1),
a_ra_bio_inc_06_1_esr AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END) >= 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mm/(1.h)' THEN o.value_num * 1.0 WHEN 'mm/1h' THEN o.value_num * 1.0 WHEN 'mm/h' THEN o.value_num * 1.0 WHEN 'mm/hr' THEN o.value_num * 1.0 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND (b.index_date + -90)
    JOIN a_ra_bio_inc_06_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 7
    WHERE o.system = 'http://loinc.org' AND o.code = '4537-7') WHERE rn = 1),
a_ra_bio_inc_06_1_crp AS (
  SELECT pid, index_date, value_num, conv, oid, effective FROM (
    SELECT b.pid, b.index_date, o.value_num, (CASE WHEN isfinite((CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END)) AND (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END) >= 0.0 THEN (CASE lower(replace(replace(replace(coalesce(o.unit, ''), ' ', ''), 'µ', 'u'), 'μ', 'u')) WHEN 'mg/dl' THEN o.value_num * 10.0 WHEN 'mg/l' THEN o.value_num * 1.0 WHEN 'ug/ml' THEN o.value_num * 1.0 ELSE NULL END) END) AS conv, o.oid, o.effective,
           row_number() OVER (PARTITION BY b.pid, b.index_date ORDER BY o.effective DESC, o.oid DESC) AS rn
    FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -180) AND (b.index_date + -90)
    JOIN a_ra_bio_inc_06_1_tjc28 a ON a.pid = b.pid AND a.index_date = b.index_date AND abs(date_diff('day', a.effective::DATE, o.effective::DATE)) <= 7
    WHERE o.system = 'http://loinc.org' AND o.code = '1988-5') WHERE rn = 1),
a_ra_bio_inc_06_1_v AS (
  SELECT b.pid, b.index_date, (CASE WHEN tjc28.conv IS NULL OR sjc28.conv IS NULL OR ptga.conv IS NULL THEN NULL WHEN esr.oid IS NOT NULL THEN (CASE WHEN esr.conv > 0 THEN 0.56 * sqrt(tjc28.conv) + 0.28 * sqrt(sjc28.conv) + 0.014 * ptga.conv + 0.7 * ln(esr.conv) ELSE NULL END) WHEN crp.conv IS NOT NULL THEN 0.56 * sqrt(tjc28.conv) + 0.28 * sqrt(sjc28.conv) + 0.014 * ptga.conv + 0.36 * ln(crp.conv + 1) + 0.96 ELSE NULL END) AS val, concat_ws(';', tjc28.oid || '|' || strftime(tjc28.effective, '%Y-%m-%d'), sjc28.oid || '|' || strftime(sjc28.effective, '%Y-%m-%d'), ptga.oid || '|' || strftime(ptga.effective, '%Y-%m-%d'), esr.oid || '|' || strftime(esr.effective, '%Y-%m-%d'), crp.oid || '|' || strftime(crp.effective, '%Y-%m-%d')) AS refs,
         (CASE WHEN tjc28.oid IS NULL OR tjc28.value_num IS NULL THEN 'derived_missing_input:tjc28' WHEN tjc28.conv IS NULL THEN 'derived_unit:tjc28' WHEN sjc28.oid IS NULL OR sjc28.value_num IS NULL THEN 'derived_missing_input:sjc28' WHEN sjc28.conv IS NULL THEN 'derived_unit:sjc28' WHEN ptga.oid IS NULL OR ptga.value_num IS NULL THEN 'derived_missing_input:ptga' WHEN ptga.conv IS NULL THEN 'derived_unit:ptga' WHEN esr.oid IS NOT NULL AND esr.value_num IS NULL THEN 'derived_missing_input:esr' WHEN esr.oid IS NOT NULL AND esr.conv IS NULL THEN 'derived_unit:esr' WHEN esr.oid IS NOT NULL AND esr.conv <= 0 THEN 'derived_missing_input:esr' WHEN crp.oid IS NULL OR crp.value_num IS NULL THEN 'derived_missing_input:crp' WHEN crp.conv IS NULL THEN 'derived_unit:crp' ELSE 'derived_missing_input' END) AS why
  FROM base b
  LEFT JOIN a_ra_bio_inc_06_1_tjc28 tjc28 ON tjc28.pid = b.pid AND tjc28.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_06_1_sjc28 sjc28 ON sjc28.pid = b.pid AND sjc28.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_06_1_ptga ptga ON ptga.pid = b.pid AND ptga.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_06_1_esr esr ON esr.pid = b.pid AND esr.index_date = b.index_date
  LEFT JOIN a_ra_bio_inc_06_1_crp crp ON crp.pid = b.pid AND crp.index_date = b.index_date),
a_ra_bio_inc_06_1 AS (
  SELECT pid, index_date, val, CASE WHEN val IS NULL THEN why ELSE refs END AS ev
  FROM a_ra_bio_inc_06_1_v),
-- RA-BIO-INC-06 (inclusion): 申請前九十日至一百八十日間另有一次 DAS28 評估大於5.1（與最近一次評估間隔至少一個月）。
c_ra_bio_inc_06 AS (
  SELECT b.pid, b.index_date, (a_ra_bio_inc_06_1.val > 5.1) AS v,
         concat_ws(';', a_ra_bio_inc_06_1.ev) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_inc_06_1 ON a_ra_bio_inc_06_1.pid = b.pid AND a_ra_bio_inc_06_1.index_date = b.index_date),
a_ra_bio_exc_01_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_01_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_01_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_ACTIVE_TUBERCULOSIS' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-01 (exclusion): 一年內有活動性結核病。
c_ra_bio_exc_01 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_ra_bio_exc_01_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ra_bio_exc_01_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ra_bio_exc_01_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_ra_bio_exc_01_1.ev, a_ra_bio_exc_01_1_off.ev, a_ra_bio_exc_01_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_exc_01_1 ON a_ra_bio_exc_01_1.pid = b.pid AND a_ra_bio_exc_01_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_01_1_nd ON a_ra_bio_exc_01_1_nd.pid = b.pid AND a_ra_bio_exc_01_1_nd.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_01_1_off ON a_ra_bio_exc_01_1_off.pid = b.pid AND a_ra_bio_exc_01_1_off.index_date = b.index_date),
a_ra_bio_exc_02_1 AS (
  SELECT pid, index_date, (o.value_code IN ('LA6576-8')) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, o.value_num AS value_num, o.value_cmp, o.value_code,
         FALSE AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE BETWEEN (b.index_date + -365) AND b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_IGRA' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
a_ra_bio_exc_02_2 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TB_PREVENTIVE_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TB_PREVENTIVE_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -365) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_02_2_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TB_PREVENTIVE_THERAPY' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_TB_PREVENTIVE_THERAPY' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-02 (exclusion): 一年內丙型干擾素釋放試驗（IGRA）陽性而未接受潛伏結核預防性治療。
c_ra_bio_exc_02 AS (
  SELECT b.pid, b.index_date, (a_ra_bio_exc_02_1.v AND (NOT (CASE WHEN (coalesce(a_ra_bio_exc_02_2.n, 0) > 0) THEN TRUE WHEN (coalesce(a_ra_bio_exc_02_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END))) AS v,
         concat_ws(';', a_ra_bio_exc_02_1.ev, coalesce(a_ra_bio_exc_02_2.ev, a_ra_bio_exc_02_2_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_exc_02_1 ON a_ra_bio_exc_02_1.pid = b.pid AND a_ra_bio_exc_02_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_02_2 ON a_ra_bio_exc_02_2.pid = b.pid AND a_ra_bio_exc_02_2.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_02_2_nd ON a_ra_bio_exc_02_2_nd.pid = b.pid AND a_ra_bio_exc_02_2_nd.index_date = b.index_date),
a_ra_bio_exc_03_1 AS (
  SELECT pid, index_date, (o.value_code IN ('LA6576-8')) AS v,
         CASE WHEN o.unit_bad THEN 'unit_mismatch;' ELSE '' END || o.oid || '|' || strftime(o.effective, '%Y-%m-%d') AS ev
  FROM (SELECT *, row_number() OVER (PARTITION BY pid, index_date ORDER BY effective DESC, oid DESC) AS rn
        FROM (SELECT b.pid, b.index_date, o.oid, o.effective, o.value_num AS value_num, o.value_cmp, o.value_code,
         FALSE AS unit_bad
  FROM base b JOIN observation o ON o.pid = b.pid AND o.effective::DATE <= b.index_date
  WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBSAG' AND vs.system = o.system AND vs.code = o.code))) o WHERE rn = 1),
a_ra_bio_exc_03_2 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBV_ANTIVIRAL_PROPHYLAXIS' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc) OR EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBV_ANTIVIRAL_PROPHYLAXIS' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -180) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_03_2_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, mid AS rid, authored AS d FROM medication x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBV_ANTIVIRAL_PROPHYLAXIS' AND vs.system = 'http://www.whocc.no/atc' AND vs.code = x.atc)) OR (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_HBV_ANTIVIRAL_PROPHYLAXIS' AND vs.system = 'https://trialbox.local/fhir/CodeSystem/nhi-drug' AND vs.code = x.nhi_code))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-03 (exclusion): B型肝炎表面抗原（HBsAg）陽性而半年內未併用抗病毒藥物預防。
c_ra_bio_exc_03 AS (
  SELECT b.pid, b.index_date, (a_ra_bio_exc_03_1.v AND (NOT (CASE WHEN (coalesce(a_ra_bio_exc_03_2.n, 0) > 0) THEN TRUE WHEN (coalesce(a_ra_bio_exc_03_2_nd.n, 0) > 0) THEN NULL ELSE FALSE END))) AS v,
         concat_ws(';', a_ra_bio_exc_03_1.ev, coalesce(a_ra_bio_exc_03_2.ev, a_ra_bio_exc_03_2_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_exc_03_1 ON a_ra_bio_exc_03_1.pid = b.pid AND a_ra_bio_exc_03_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_03_2 ON a_ra_bio_exc_03_2.pid = b.pid AND a_ra_bio_exc_03_2.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_03_2_nd ON a_ra_bio_exc_03_2_nd.pid = b.pid AND a_ra_bio_exc_03_2_nd.index_date = b.index_date),
a_ra_bio_exc_04_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -1825) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_04_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MALIGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_04_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_MALIGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_MALIGNANCY' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -1825) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-04 (exclusion): 五年內有惡性腫瘤病史。
c_ra_bio_exc_04 AS (
  SELECT b.pid, b.index_date, (CASE WHEN (coalesce(a_ra_bio_exc_04_1.n, 0) > 0) THEN TRUE WHEN coalesce(a_ra_bio_exc_04_1_off.n, 0) > 0 THEN NULL WHEN (coalesce(a_ra_bio_exc_04_1_nd.n, 0) > 0) THEN NULL ELSE FALSE END) AS v,
         concat_ws(';', coalesce(a_ra_bio_exc_04_1.ev, a_ra_bio_exc_04_1_off.ev, a_ra_bio_exc_04_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_exc_04_1 ON a_ra_bio_exc_04_1.pid = b.pid AND a_ra_bio_exc_04_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_04_1_nd ON a_ra_bio_exc_04_1_nd.pid = b.pid AND a_ra_bio_exc_04_1_nd.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_04_1_off ON a_ra_bio_exc_04_1_off.pid = b.pid AND a_ra_bio_exc_04_1_off.index_date = b.index_date),
a_ra_bio_exc_05_1 AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code)) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -280) AND b.index_date
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_05_1_nd AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|', ';' ORDER BY e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code) OR (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_PREGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code)))) e ON e.pid = b.pid AND e.d IS NULL
  GROUP BY b.pid, b.index_date),
a_ra_bio_exc_05_1_off AS (
  SELECT b.pid, b.index_date, count(*) AS n,
         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_PREGNANCY' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_PREGNANCY' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -280) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-05 (exclusion): 懷孕中（二百八十日內有懷孕診斷）。
c_ra_bio_exc_05 AS (
