         concat_ws(';', coalesce(a_ra_bio_exc_05_1.ev, a_ra_bio_exc_05_1_off.ev, a_ra_bio_exc_05_1_nd.ev)) AS ev
  FROM base b
  LEFT JOIN a_ra_bio_exc_05_1 ON a_ra_bio_exc_05_1.pid = b.pid AND a_ra_bio_exc_05_1.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_05_1_nd ON a_ra_bio_exc_05_1_nd.pid = b.pid AND a_ra_bio_exc_05_1_nd.index_date = b.index_date
  LEFT JOIN a_ra_bio_exc_05_1_off ON a_ra_bio_exc_05_1_off.pid = b.pid AND a_ra_bio_exc_05_1_off.index_date = b.index_date),
