         string_agg(e.rid || '|' || strftime(e.d, '%Y-%m-%d'), ';' ORDER BY e.d, e.rid) AS ev
  FROM base b JOIN (SELECT pid, cid AS rid, coalesce(onset, recorded) AS d FROM condition x WHERE (EXISTS (SELECT 1 FROM vsf WHERE vsf.vs_id = 'VS_SERIOUS_INFECTION' AND vsf.system = x.system AND starts_with(x.code, vsf.prefix)) AND NOT EXISTS (SELECT 1 FROM vs WHERE vs.vs_id = 'VS_SERIOUS_INFECTION' AND vs.system = x.system AND vs.code = x.code))) e ON e.pid = b.pid AND e.d BETWEEN (b.index_date + -30) AND b.index_date
  GROUP BY b.pid, b.index_date),
-- RA-BIO-EXC-06 (exclusion): 三十日內有嚴重感染（敗血症、肺炎）。
c_ra_bio_exc_06 AS (
